var userF = CompletableFuture.supplyAsync(() -> userApi.get(uid), pool);
var orderF = CompletableFuture.supplyAsync(() -> orderApi.list(uid), pool);
var pointF  = CompletableFuture.supplyAsync(() -> pointApi.sum(uid), pool);

CompletableFuture.allOf(userF, orderF, pointF).join();
return new Page(userF.join(), orderF.join(), pointF.join());
